        else:
            target = max(68.0, avg_prev * 0.72)
        return float(min(budget, target))

    if low_supply:
        if max_prev >= 130.0:
            target = 61.0 if hp >= 7 else 86.0
        elif max_prev >= 110.0:
            target = 74.0
        else:
            target = max(58.0, max_prev + 1.0)
        if desperate_count >= 2:
            target += 6.0
        return float(min(budget, target))

    if high_supply:
        target = 24.0
        if max_prev < 80.0:
            target = 36.0
        if day >= 8 and hp <= 6:
            target = 48.0
        return float(min(budget, target))

    target = 38.0
