def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = int(day_context['supply'])
    alive = {k: v for k, v in opponents_status.items() if v.get('alive')}

    y_bids = []
    for opp in alive.values():
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            y_bids.append(trace['bid'])

    if my_status['hp'] <= 2:
        bid = min(my_status['budget'], 0.9 * DAILY_SALARY)
    elif not y_bids:
        bid = min(my_status['budget'], 0.6 * DAILY_SALARY)
    else:
        avg_y = sum(y_bids) / len(y_bids)
        if avg_y > 120:
            bid = min(my_status['budget'], 0.6 * DAILY_SALARY)
        elif avg_y < 100:
            target = avg_y + 1.5
            bid = min(my_status['budget'], max(DAILY_SALARY * 0.4, target))
        else:
            bid = min(my_status['budget'], 0.7 * DAILY_SALARY)

    bid = max(bid, 1.0)
    bid = min(bid, my_status['budget'])
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    DAYS_IN_EPISODE = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_competitors = len(alive_opponents) + 1 # Myself + alive opponents

    # Calculate available water slots
    num_slots = int(day_context['supply'] // WATER_REQ)

    # If no opponents are alive, bid low to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine highest previous bid to gauge competition
    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    my_hp = my_status['hp']
    my_budget = my_status['budget']

    # Strategy based on HP and competition
    # Critical HP: Must get water
    if my_hp <= 2:
        # Bid very aggressively, ensuring I outbid high bidders
        bid_amount = max(DAILY_SALARY * 0.95, highest_prev_bid + 5.0)
        return min(my_budget, bid_amount)

    # Low HP: Need water soon
    elif my_hp <= 4:
        # Bid aggressively, but slightly less than critical
        bid_amount = max(DAILY_SALARY * 0.85, highest_prev_bid + 2.0)
        return min(my_budget, bid_amount)

    # Moderate/Good HP: Can try to conserve budget but stay competitive
    else:
        # If supply is very tight (fewer slots than competitors)
        if num_slots < num_alive_competitors:
            # Still need to be competitive, as high bidders exist
            bid_amount = max(DAILY_SALARY * 0.75, highest_prev_bid + 1.0)
            return min(my_budget, bid_amount)
        else:
            # More relaxed, can bid a bit lower, but still above known low bidders
            bid_amount = max(DAILY_SALARY * 0.6, highest_prev_bid + 0.5)
            return min(my_budget, bid_amount)

    # Fallback (should not be reached under normal circumstances)
    return min(my_budget, DAILY_SALARY * 0.5)
